from functools import reduce

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    key = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (0, 8)]
    mask = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not key or not mask:
        return out
    runs = []
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == 8]
        n = 0
        for i, c in enumerate(cols):
            if i and c != cols[i-1] + 1:
                runs.append(n); n = 0
            n += 1
        if n:
            runs.append(n)
    scale = reduce(gcd, runs) if runs else 1
    r0 = min(r for r, c in mask)
    c0 = min(c for r, c in mask)
    mr0 = min(r for r, c, v in key)
    mc0 = min(c for r, c, v in key)
    # Key and silhouette share a tile lattice; retain the key's colors at
    # corresponding positions, and use repeated key marks to complete holes.
    tile_colors = {}
    for r, c, color in key:
        tile_colors[((r-mr0)//scale, (c-mc0)//scale)] = color
    mask_tiles = {}
    for r, c in mask:
        mask_tiles.setdefault(((r-r0)//scale, (c-c0)//scale), []).append((r,c))
    assigned = {}
    for tilepos in mask_tiles:
        if tilepos in tile_colors:
            assigned[tilepos] = tile_colors[tilepos]
    # Any key marks outside the silhouette represent same-color repetitions
    # that complete the nearest available silhouette tiles.
    extras = []
    for pos, color in tile_colors.items():
        if pos not in mask_tiles:
            extras.append((pos, color))
    for pos, color in extras:
        candidates = [p for p in mask_tiles if p not in assigned]
        if not candidates:
            break
        target = min(candidates, key=lambda p: (abs(p[0]-pos[0])+abs(p[1]-pos[1]), p))
        assigned[target] = color
    for pos, color in assigned.items():
        for r, c in mask_tiles[pos]:
            out[r][c] = color
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
